 def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid))
    # For each isolated mark, extend diagonally along the sequence's local slope;
    # edge stripes define the two opposite endpoints of the track.
    marks=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and r not in (0,h-1) and c not in (0,w-1)]
    for r,c in marks:
        # choose nearest border run by Manhattan distance
        borders=[]
        for j,v in enumerate(grid[0]):
            if v!=bg: borders.append((abs(r)+abs(c-j),0,j))
        for j,v in enumerate(grid[-1]):
            if v!=bg: borders.append((abs(h-1-r)+abs(c-j),h-1,j))
        if not borders: continue
        _,tr,tc=min(borders)
        dr=1 if tr>r else -1 if tr<r else 0
        dc=1 if tc>c else -1 if tc<c else 0
        out[r][c]=4
        y,x=r+dr,c+dc
        while 0<=y<h and 0<=x<w and grid[y][x]==bg:
            out[y][x]=grid[r][c]; y+=dr; x+=dc
    return out


