 def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    # In the demonstrated task, a diagonal pair encodes a line extension; a
    # singleton or a multi-cell block is left unchanged.
    for color in {v for row in g for v in row if v != bg}:
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        if len(pts) != 2:
            continue
        (r1, c1), (r2, c2) = sorted(pts)
        dr, dc = r2-r1, c2-c1
        if abs(dr) != 1 or abs(dc) != 1:
            continue
        for r, c, sr, sc in ((r1-dr, c1-dc, -dr, -dc),
                             (r2+dr, c2+dc, dr, dc)):
            while 0 <= r < h and 0 <= c < w and g[r][c] == bg:
                g[r][c] = color
                r += sr
                c += sc
    return g
