 def transform(grid):
    # Uniform separator rows/columns partition the grid into cells. Count
    # non-background values in each cell; a single outlier remains its color,
    # while multiple outliers map to 1.
    rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    cols = [j for j in range(len(grid[0])) if len({grid[i][j] for i in range(len(grid))}) == 1]
    rb = [-1] + rows + [len(grid)]
    cb = [-1] + cols + [len(grid[0])]
    out = []
    for r0, r1 in zip(rb, rb[1:]):
        line = []
        for c0, c1 in zip(cb, cb[1:]):
            cells = [grid[r][c] for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)]
            background = max(set(cells), key=cells.count)
            count = sum(value != background for value in cells)
            line.append(1 if count >= 2 else background)
        out.append(line)
    return out
